### 5. Direct Code (as reconstructed from context)

```cpp
bool AmendmentSet::passes(uint256 const& amendment) const {
    auto const& it = votes_.find(amendment);
    if (it == votes_.end())
        return false;
    return it->second >= threshold_;
}
```

